  args.push('--dangerously-bypass-approvals-and-sandbox', '--json', '--skip-git-repo-check');
  if (reasoningEffort) {
    args.push('-c', `model_reasoning_effort="${reasoningEffort}"`);
  }
  if (verbosity) {
    args.push('-c', `model_verbosity="${verbosity}"`);
  }
  args.push(input.prompt);
